-- Mod-authored great work descriptions, ja_JP overlay.
-- Baseline in CivVAccess_GreatWorkDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_MISSING"] =
    "この偉大な芸術作品には絵の解説がありません."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIRL_WITH_PEARL_EARRING"] =
    "オランダ黄金時代の油彩画で, 西洋美術で最も愛された肖像の一つだ. 若い女性が無地の暗い背景から肩越しに振り返ってこちらの目を見つめ, 今にも口を開こうとするように唇をわずかに開いている. 青と金のターバンを巻き, その布は背中へ垂れ下がり, 耳元では一粒の大きな涙形の真珠が光を捉えている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HENRY_VIII"] =
    "テューダー朝の宮廷肖像を描いた油彩画で, 世界がヘンリー8世を思い描く姿を定めた一枚だ. 王は全身でこちらに正対して立ち, 両足を大きく開き, 肩幅が広く重厚な体で, 片手を腰の短剣に添えている. 宝石をちりばめた銀のダブレットの上に毛皮裏の深紅のコートを羽織り, 平たい羽根飾りの帽子をかぶり, 金の鎖をいくつも掛け, 大理石の柱の間の文様の絨毯の上に立っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HUNTERS_IN_THE_SNOW"] =
    "フランドル・ルネサンスの油彩画で, 丘の頂から見下ろした冬の風景だ. 前景では3人の疲れた狩人と猟犬の群れが深い雪をかき分けて進み, うつむき, 獲物は1匹の狐だけだ. その下には灰緑色の空の下に村が広がり, 凍った池では小さなスケーターたちが遊び, 遠くには切り立った峰がそびえている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LES_DEMOISELLES"] =
    "初期モダニズムの油彩画で, キュビスムの口火を切った画布だ. 5人の裸の女性が, ぎざぎざのピンク, 白, 青の平面が連なる浅い空間に立ち, あるいは座り, その体は鋭い角ばった形に砕かれている. 右側の2つの顔はアフリカの仮面のように描かれ, 縞模様で歪められている. 一方ほかの女性たちは大きなアーモンド形の目で真っすぐにこちらを見据えている. 画面の下端には小さな果物の鉢が置かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LUNCHEON"] =
    "フランス印象派の油彩画で, 食事の後も名残を惜しむ友人たちを描いている. 夏服に身を包んだ陽気な一団が, 縞模様のオレンジと白の日除けの下, 川辺のバルコニーにあふれるように集まり, 語らい, 戯れ, 手すりにもたれている. 手前の若い女性は小さな犬と遊んでいる. テーブルにはワインの瓶, グラス, 果物が散らばり, すべてが日差しの色を温かく緩やかな筆触で描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MONA_LISA"] =
    "イタリア・ルネサンスの板に描かれた油彩画で, おそらく世界で最も有名な肖像だ. 一人の女性が両手を組んで座り, 曲がりくねった川と遠くの青い山々が霞む風景を背に, わずかにこちらへ向き直っている. その目は真っすぐにこちらの目を捉え, どこに立っても追ってくるように思える有名な眼差しだ. かすかな半ば微笑みがこの絵の焦点で, 柔らかな茶と緑で硬い輪郭線なしに描かれ, 見つめるほどに表情が移ろうように感じられる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUNDAY_AFTERNOON"] =
    "点描の油彩画で, 純色の小さな点だけで組み立てられている. 日曜の晴れ着のパリの人々が, 日の当たる川辺の芝生でくつろぎ, パラソルを差して散策し, 草の上に寝そべり, 小さな犬を連れて歩き, その後ろの水面には帆船が浮かぶ. 誰もが不思議なほど静かで格式ばっており, 浮き彫りの中の人物のようで, 光は緑, オレンジ, すみれ色の斑点のきらめきへと砕かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VIEW_OF_TOLEDO"] =
    "スペイン・ルネサンスの油彩画で, 西洋美術で最も初期の純粋な風景画の一つであり, 異例なほど暗い一枚だ. スペインの丘の都市トレドが, 荒れ狂う嵐の空の下, 遠くにそびえ立ち, 灰色の尖塔と城壁が不気味な銀色の光に照らされている. 緑の丘が前景の川へと転がり落ち, 場面全体が深い緑と青みがかった黒で描かれ, 昼の光景というより夢のように感じられる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WATER_LILIES"] =
    "フランス印象派の油彩画で, ジヴェルニーの庭の池を描いたモネの有名な連作の一つだ. 画布全体が水面そのもので, 水平線も岸もない. 緑の睡蓮の葉の浮き島が, ピンクと赤の花を点々と散らした青とラベンダー色の水面を漂っている. 雲と木々は柔らかな反映としてのみ現れ, 筆触はすべてが漂うように見えるほど緩やかだ."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_STARRY_NIGHT"] =
    "ポスト印象派の油彩画で, 近代美術で最もよく知られた図像の一つだ. 動きに満ちた夜空が画布の大半を占めている. 星々は渦巻く光輪の中で燃え, 隅では月がオレンジ色に燃え, 大きな螺旋の流れが空の中央を横切って渦を巻く. その下では尖った教会の尖塔を持つ静かな村が丘の間で眠り, 暗い糸杉が左端を炎のように立ち上り, すべてが青と金の厚く目に見える筆致で描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BIRTH_OF_VENUS"] =
    "イタリア・ルネサンスの絵画で, 海から到来する愛の女神を描き, 古典神話の最も有名な図像の一つだ. ヴィーナスは巨大なホタテ貝の上に裸で立ち, 両手と長い金色の髪のひと束で身を覆っている. 左では2人の翼を持つ風の神がピンクのバラの雨を降らせながら彼女を岸へと吹き寄せ, 右では花柄のドレスの女性が, はためく外套で彼女を包もうと駆け寄っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BINDO_ALTOVITI"] =
    "イタリア盛期ルネサンスの油彩肖像画で, 裕福な若いローマの銀行家を描いている. 長い金色の髪と黒い帽子の美しい若者が, 剥き出しの肩越しにこちらを振り返り, 片手を胸へ引き寄せている. 黒い衣服の上に青いマントを羽織り, その青白い顔は深い緑の背景を背に輝いている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_DRAGON"] =
    "初期イタリア・ルネサンスの絵画で, おとぎ話のように硬く絵本めいた趣がある. 右では甲冑の騎士が前足を上げた白馬に乗り, 蛾のような斑点のある翼を持つ緑の竜の開いた顎に槍を突き入れている. 左では長いピンクのガウンをまとった落ち着いた王女が, 暗い洞窟の前で, 傷ついた獣をペットのように引き綱でつないでいる. 騎士の背後には奇妙な螺旋状の嵐が湧き起こっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CREATION_OF_ADAM"] =
    "システィーナ礼拝堂の天井に描かれたイタリア・ルネサンスのフレスコ画で, 美術で最も有名な仕草の一つの源だ. 裸のアダムが左側の緑の丘に身を横たえ, 片腕を力なく差し伸べている. 一方右側からは, 天使たちに満ちたはためくばら色の覆いをまとった灰色の顎鬚の人物, 神が押し寄せてくる. 互いに伸ばした人差し指が狭い隙間を越えて触れ合おうとし, 命の火花がきらめく直前の瞬間だ."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GALLERY_OF_THE_LOUVRE"] =
    "ルーブルのギャラリーの内部を描いたアメリカの油彩画で, 後に電信の符号を発明したのと同じモースが描いた. 赤い壁の壮大なサロンが床から天井まで, 金縁に収められた数十点の巨匠絵画で埋め尽くされ, その中には小さなモナ・リザもある. 前景では美術学生たちがイーゼルに向かって模写をして座り, 教師が若い女性の肩越しに身を乗り出して彼女の作品を直しており, 遠くにはさらなる展示室へと続くアーチ形の回廊が開けている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WASHINGTON_CROSSING"] =
    "デラウェア川を渡るワシントン, 油彩による英雄的なアメリカ史画で, 独立戦争の象徴だ. ワシントン将軍が混み合った漕ぎ舟の舳先にまっすぐ立ち, 兵士たちは氷の塊で埋め尽くされた川を竿で押し漕ぎ渡り, 彼の後ろでは士官がアメリカ国旗を高く掲げている. 冷たい霞を破って夜明けの光が差し込み, 後方には兵士や馬を満載した舟がさらに続いている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ARRANGEMENT_IN_GREY"] =
    "灰色と黒のアレンジメント: 母の肖像, ホイッスラーの母として広く知られるアメリカの油彩画だ. 長い黒のドレスと白いレースの帽子をまとった年配の女性が, 左を向いた厳格な横顔で座り, 両手を膝の上で組み, 足を小さな足台に乗せている. 室内は簡素で平板で, 灰色の壁, 暗い文様のカーテン, そして額装された絵が一枚あるだけで, 構図全体がまさに題名の通り, 灰色と黒の習作のように釣り合いを保っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BREEZING_UP"] =
    "ニューイングランド沖の小舟の帆走を描いたアメリカの写実主義の油彩画, 風を受けて(順風)だ. 一人の男と三人の少年が, グロスターと名付けられた小さなキャットボートの中で身を後ろにそらし, 舟は強い風を受けて傾き, 舳先からは飛沫が上がり, 足元にはその日の漁獲が積まれている. 海は切れ切れの雲の下で荒れた緑色をなし, 水平線には二本マストのスクーナーが浮かんでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_THOUSAND_LI"] =
    "千里江山, 宋朝の宮廷に仕えた十代の天才が絹に描いた青緑の山水の手巻きで, 全長は十二メートル近い. 鮮やかな鉱物質の青と緑をなす山々が, 穏やかな金色の川から尾根を連ねて次々と立ち上がり, 斜面の合間には小さな村, 橋, 葉のない木々が点在している. 筆で書かれた書の縦列と収集家の朱印が, 峰々の上の空を埋め尽くしている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DWELLING_IN_THE_FUCHUN"] =
    "富春山居圖, 元朝の文人山水画の傑作である水墨の手巻きで, 紙の上に黒い墨の濃淡だけで全て描かれている. 重なる乾いた筆致で築かれた丸みのある山々が広く穏やかな川の上に立ち上がり, 岸辺には松, 点在する小屋, 漁舟が並ぶ. 趣はゆったりとして瞑想的であり, 何世紀にもわたる愛好家たちが押した収集家の朱印が紙面に点々と散らばっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ALONG_THE_RIVER"] =
    "清明上河図, 絹に描かれた宋朝の手巻きで, 全長五メートルを超える日常の都市生活の名高い大画面だ. 示された部分は都の大きな城門, すなわち傾斜した城壁の上にそびえる巨大な木造の楼を中心に据え, その下の街路は活気に満ちている. 市の露店, 牛車, 城門を通り抜けるラクダの隊商, そして天秤棒で荷を担ぐ運搬人たちが見える. どの人物も小さいが, 細い墨の線と抑えた土色で精緻に描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LEAF_2"] =
    "畫仕女圖, 清朝の冊子の一葉で, 繊細な線と淡い彩色による宮廷画だ. 白, 緑, 青の長く流れるローブをまとった優美な女性たちが, 鮮やかな青い布を垂らした庭の東屋に集い, 一人は赤い欄干の奥の卓で香を焚いている. 彼女たちの周りには庭石, 竹, そして東屋の屋根に這い上る花のつるがある."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EMPEROR_TAIZONG"] =
    "歩輦図, 絹に描かれた唐朝の手巻きで, 外交の謁見を記録した宮廷の図だ. 右側では太宗皇帝が宮女たちに担がれた台に座り, 彼女たちはまた二本の大きな団扇と頭上の赤い天蓋も支えている. 左側では三人の小さな人物が恭しい姿勢で進み出る. 赤い装束の宮廷の案内役, 文様のあるローブをまとったチベットの使節, 白衣の通訳で, いずれも朱印で覆われた温かい金色の絹を背にしている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SPRING_MORNING"] =
    "漢宮春曉, 絹に描かれた明朝の手巻きで, 春の朝にくつろぐ宮廷の女性たちを描いた長い大画面だ. 数十人の優美な女性たちが開かれた殿堂, 縁側, 中庭を埋め尽くし, 音楽を奏で, 肖像を描き, 子供と遊び, 柳や庭石, さらには孔雀の間を歩いている. 宮殿の建築が温かい赤と緑をなして巻物の全長にわたって続き, あらゆる衝立, 欄干, ローブが綿密な細い線で描き込まれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_GREAT_WAVE"] =
    "神奈川沖浪裏, 日本美術で最も名高い一枚である浮世絵の木版画だ. 巨大な深い青の波が左側でそそり立ち, 場面全体を覆って巻き上がり, その頂は鉤爪のような白い泡の指へと砕けている. その下では漕ぎ手を満載した三艘の長い屋根のない舟が波間を進み, 遠くその全ての中心に小さく, 雪をいただいた富士山の円錐が見える."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EVENING_SHOWER"] =
    "大はしあたけの夕立, これまで作られた中で最も称賛される雨の場面の一つである浮世絵の木版画だ. 細い斜めの線の幕として描かれた突然の豪雨が, 長い木の橋を渡る途中の人々を捉える. 彼らは笠や傘の下を両方向へ急ぎ, 一人は藁の蓆の下に身を隠している. 下の川は青緑の帯をなし, 一人の筏師が竿を差して進み, 対岸は嵐の下で暗い染みへとかすんでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_L_ABSINTHE"] =
    "サブサントゥ, パリのカフェ生活を容赦なく描いたフランス印象派の油彩画だ. 淡い色のドレスと帽子をまとった女性が大理石のカフェのテーブルにうなだれて座り, 視線を落とし, 前には乳白色の緑のアブサンのグラスが置かれている. その隣では顎鬚を生やした男がよれよれのコートを着て口にパイプをくわえ, 右の方へ目をやっている. 二人はともに座りながらも全く隔たっており, この絵が漂わせる孤独の気配を伝える, くすんだ灰色と茶色で描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_UPAUPA_SCHNEKLUD"] =
    "チェロ奏者の肖像, 演奏中のチェリストを描いたポスト印象派の油彩肖像画だ. 奏者は鮮やかなオレンジ赤のチェロの上にかがみ込み, 集中して目を伏せ, 弓を持つ腕が弦の上を滑り, 濃い青のスーツが楽器の輝きを縁取っている. 彼の背後では背景が茶色と苔色の緑の平らな領域に分かれ, 淡い抽象的な形が散らばっており, ゴーギャンの大胆で単純化された色彩様式による."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_BAR_AT_THE_FOLIES"] =
    "フランスの近代生活を描いた油彩画で, マネ最後の傑作である. 黒いビロードのボディスに胸元へ花を挿したバーの女が, シャンパンの瓶, オレンジを盛った鉢, 薔薇を活けたグラスで埋め尽くされた大理石のカウンターの後ろに立ち, 疲れた遠い眼差しでこちらを見つめている. 彼女の背後では巨大な鏡が, きらめく音楽堂とそのシャンデリア, 群衆を映し出し, さらに奇妙に右へずれた位置に, シルクハットの男へ身を乗り出す彼女自身の背中を映している."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BALL_AT_THE_MOULIN"] =
    "かの有名なキャバレーのパリの夜の生活を描いた, ポスト印象派の油彩画である. シルクハットの男たちと羽根飾りの帽子の女たちの一団が, 飲み物を前にテーブルを囲んで座り, その後ろの緑の光に照らされたダンスホールでは赤毛の女が髪を直している. 右端には女の顔が大きく迫り, 下方から不気味な緑の光に照らされ, 前景には長い斜めの手摺りがロートレックのポスターのような様式で横切っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS"] =
    "ウィーンのアール・ヌーヴォーの油彩画で, 本物の金箔を重ねて施した, クリムト最も名高い作品である. 花の咲く草地の上で一組の男女が抱き合って膝をつき, 男は身をかがめて女の頬に口づけし, 女は目を閉じて顔を上向ける. 二人の体は1枚の金色のマントへと溶け合い, 男には長方形の, 女には鮮やかな円形の文様が施され, 平らに揺らめく金色の背景に対して輝いている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AMERICAN_GOTHIC"] =
    "アメリカ地方主義の油彩画で, 数限りなくパロディにされ, ひと目で見分けがつく. 丸眼鏡をかけデニムのオーバーオールを着た, 厳格な顔つきで頭の禿げた農夫が, 三叉の熊手を垂直に立てて握り, その傍らに暗い柄のエプロンドレスの女が, 口を引き結んだ非難の面持ちでよそを見ている. 二人の背後には, この絵の名の由来となった白い農家が立ち, その切妻には尖頭アーチのゴシック窓がはまっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SRI_SHANMUKAHA"] =
    "ラヴィ・ヴァルマがインド各地で広めたヨーロッパのアカデミー様式によるインドの信仰画である. ヒンドゥー教の神ムルガンが, 冠を戴く6つの頭と武器を持つ多くの腕とともに孔雀の乗物にまたがり, 鮮やかなピンクのサリーをまとう2人の妃を左右に従えている. 孔雀の尾は緑と金の巨大な目玉模様の扇のように一同の背後に広がり, その鳥は足の下にコブラを押さえつけている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DAUD_RECEIVES_A_ROBE"] =
    "挿絵入りの帝国年代記からのムガル細密画で, 紙に不透明な水彩と金で描かれている. ここに示された部分は, 淡い色のローブ, 赤い帽子, 金の帯を身に着けた, ほっそりとした若い従者を中心としており, 拝謁の儀のためにたたまれた金の名誉の衣を捧げ持っている. 彼は繊細な花の蔓に覆われた鮮やかな青いテントの壁を背に立ち, ひだも花も一つ残らず細密画の精度で描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YUSEF_AND_ZULEYKHA"] =
    "挿絵入りの写本からのペルシア細密画で, ヘラートの巨匠ベフザードの最も名高い作品である. 画面は, 平面的な断面図で描かれた複雑な宮殿, すなわち階段, バルコニー, 戸口が入り組み, 青, 橙, 金のタイルで装飾された迷宮で埋め尽くされている. 上の一室では炎の光輪を負った預言者ユースフが, 手を差し伸べるズライハの手から逃れ, ペルシア語の書のパネルが建築を縁取っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ASCENT_OF_MUHAMMAD"] =
    "王室写本からのペルシア細密画で, 預言者の夜の天界の旅を描いている. ムハンマドは, 顔を白い布で覆われ金色の炎に包まれて, 人の頭を持つ乗馬ブラークにまたがり, 渦巻く金縁の雲が散らばる深い青の空を渡っていく. 赤, 緑, 橙のローブをまとった天使たちが, 贈り物や香炉を携え, あらゆる方角から彼を取り巻いて舞い, ペルシア語の詩句の行がこの情景を縁取っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LIBERTY_LEADING_THE_PEOPLE"] =
    "フランス・ロマン主義の油彩画で, 革命を象徴する決定的な図像である. 自由の女神その人, 黄色いドレスに赤い帽子を被った胸をはだけた女が, 瓦礫と倒れた死体の築いたバリケードを越えて進み, フランスの三色旗を煙る空へ突き上げている. その周りには, シルクハットにマスケット銃を持つ紳士や2丁の拳銃を振りかざす少年を含む, あらゆる階級の武装した市民が押し寄せる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_JEROME_IN_HIS_STUDY"] =
    "目を見張る細密の精度で描かれた, 初期ルネサンスの油彩画である. 壮大な石のアーチ越しに見えるのは, 丸天井の聖堂空間の中に舞台のように作られた木製の書斎で, 赤いローブの聖ヒエロニムスが本を読みながら座り, 棚の書物や壺に囲まれている. 光は四方の窓から差し込み, 手前の敷居には孔雀と山鶉がとまり, 右手の影の中では彼のライオンがうろついている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PARTHENON_FRIEZE"] =
    "古代アテネを想像して描いたヴィクトリア朝の油彩画で, このゲームではパルテノン神殿の遺産に付属する. 彫刻家ペイディアスが, 描き上げたばかりの騎馬像の大理石のフリーズの脇の木製の足場に立ち, まだ工房の彩色を残したそれを, 綱を引いて押さえながら披露している. ひだのあるローブをまとったアテネ人の一団, その中にはペリクレスもいて, 神殿内部の温かな光のもと身を乗り出して彫刻に見入っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUE_DE_PARIS"] =
    "霧雨の日の近代パリを描いたフランス写実主義の油彩画で, 印象派の仲間たちが大らかであったのに対し, 鋭く写真のように精密である. 1本の傘を分け合う身なりのよい男女が, 濡れて光る石畳の上をこちらへ歩いてきて, 男はシルクハットを被り, 女は長い暗色のドレスを着て耳飾りが光を受けている. 二人の周りでは傘を差した他の歩行者たちが, 楔形の灰色の集合住宅に囲まれた広い交差点を渡り, 緑の街灯柱が画面を中央で二つに割っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_NIGHT_WATCH"] =
    "巨大な画面に描かれたオランダ黄金時代の油彩画で, これまでに作られた最も有名な集団肖像画である. 市民自警団の一隊が深い影の中から動き出す. 赤い飾り帯の黒装束の隊長が前へ進み出て, 淡い金色の服の副官に命令を下し, その背後ではマスケット銃に弾が込められ, 軍旗が掲げられ, 鼓手が拍子を打っている. 輝く金色のドレスを着た小さな少女が群衆の中で謎めいて光り, 薄暗がりの中でスポットライトのように照らされている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DEATH_OF_MARAT"] =
    "フランス新古典主義の油彩画で, フランス革命の偉大な殉教者の図像である. 革命派の記者マラーが浴槽の中で死んで横たわり, 倒れた聖人のようにくずおれ, 頭は白いターバンで包まれ, 片腕は床へ垂れて今なお羽ペンを握っている. もう一方の手には, 暗殺者が押し入るのに用いた手紙が握られている. 画面の上半分は何もない暗い壁で, 傍らの素朴な木箱には A Marat, David. という献辞が描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ETIENNE_CHEVALIER"] =
    "フランス後期中世の板絵で, 名高い信仰用の二連祭壇画の片翼である. 国王の出納官エティエンヌ・シュヴァリエが豊かな赤いローブを纏って跪き, 両手を合わせて祈っており, 彼の守護聖人である聖ステパノに付き添われている. 聖ステパノは青と金の祭服を着て傍らに立ち, ぎざぎざの石を載せた書物を持つ. これは彼の殉教の象徴だ. 二人は白い大理石の広間に立ち, 寄進者の名が壁面に沿って刻まれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_FRANCIS"] =
    "スペイン・バロックの油彩画で, 修道士の厳しい信仰を描く. 聖フランシスが砂の色をした飾り気のないフードつきの修道服を纏い, 一人で立つ. 顔は頭巾の深い影に半ば沈み, 伏せた目で祈っている. 死を思い起こすよすがとして人間の頭蓋骨を両手に抱き, ほぼ真っ黒な背景に対して, ただ一筋の硬い光に照らされている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HATAORI"] =
    "機を織る女を描いた日本の浮世絵木版画である. 文様のある藍染めの着物を着た若い女が, 裸足で大きな木製の手織機に座り, 片手に杼を持って仕事から顔を上げてこちらを見ている. 赤, 青, 白の糸が機の端から端まで張り渡されている. 色合いは柔らかなクリーム色と落ち着いた青で, 紙の左上には筆書きの詩が一列に書き連ねられている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JANE_GREY"] =
    "フランス・アカデミーの歴史画で, 芝居がかって胸を打つ. 十代の女王が目隠しをされ, 暗い石造りの広間に映える白いサテンを纏い, 跪いて手探りで処刑台を探っており, 年配の役人がその手をそっと台へと導いている. 彼女の侍女たちは背後の柱にもたれて悲嘆に崩れ落ち, 処刑人は右側で斧にもたれ, 目を背けて待っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WANDERER"] =
    "ドイツ・ロマン主義の油彩画で, 自然の前に一人立つ人間を描いた象徴的な一枚である. 暗い緑のコートを着た若い男が, こちらに背を向けて岩の頂に立ち, 杖にもたれ, 風に髪をなびかせている. 彼の下には白い霧の海が谷を呑み込み, 尾根や岩峰だけが島のように突き出て, 淡い山々が遠くへと霞んでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BABEL"] =
    "フランドル・ルネサンスの油彩画で, 聖書に描かれた破滅の塔を細部まで満ちあふれるように描く. 巨大な螺旋状のアーチの塔は, 一部が白い石, 一部がむき出しの赤い煉瓦でできており, 傾きながら雲の中へとそびえ立ち, その頂はまだ造りかけの未完成のままだ. 塔の足元には船が停泊する港町が広がり, 前景では王が石工の一団を検分し, 彼らは切石の間で王の足元に跪いている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YOUNG_LADY"] =
    "初期ネーデルラントの油彩肖像画で, 小さく, 静かで, 不思議なほど近代的である. 磁器のように滑らかな顔をした青白い若い女が, 金で縁取られた背の高い黒いビロードの頭飾りの下から, 斜めにこちらを見ている. 白い毛皮の衿のついた青いガウンを纏い, 金と黒の細い帯を連ねたぴったりした首飾りを着け, 通常の暗い闇ではなく, 飾り気のない薄暗い壁を背にしている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_KINDRED"] =
    "アメリカのハドソン・リバー派の油彩画で, ある画家と詩人の友情に捧げられた一枚である. コートを着た二人の男が, キャッツキル山地の森の峡谷の上に張り出した岩棚に立って語らい, 一人は筆で眺望のほうを指し示している. 下では小川が岩を伝って流れ落ち, 張り出した木々のアーチに縁取られ, 背後には霞んだ峰々が金色の光の中へ溶け込んでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BLUE_BOY"] =
    "イギリスのグランド・マナーの油彩肖像画で, この画家の最も有名な作品である. 十二歳ほどの少年が, 半ズボンとレースの衿をあしらった煌めく青いサテンの装いで全身像として立ち, 片手を腰に当て, もう一方の手で羽根飾りのついた帽子を脇に提げている. 暗く嵐めいた茶色の風景を背に, くつろいだ自信をもってこちらを見ており, その風景が青い衣装をいっそう燃え立たせている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SECOND_OF_MAY"] =
    "スペインの油彩画で, 絵画における戦争への最初にして最も偉大な抗議の一つである. ランタンの光の中, フランスの銃殺隊が無表情な一列に並び, マドリード郊外の何もない丘で身を寄せ合うスペインの捕虜たちに銃を向けている. 中央では白いシャツの男が銃口の前で両腕を大きく広げ, すでに撃たれた者たちの亡骸の間に跪いており, その姿は磔刑を思わせる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_CART"] =
    "普仏戦争を題材としたフランスの軍事油彩画で, 不屈の最後の抵抗を描いた名高い一枚である. 一握りのフランス兵が破壊された村の家を守り, 窓から銃撃する一方で, 負傷者は壁にもたれて座り込み, 一人の士官が残りわずかな弾薬を数えている. 部屋は荒れ果て, 扉は蝶番から外れ, 天井から漆喰が落ち, 戦友たちがなお戦う戸口からは日の光が射し込んでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EARLY_AUTUMN"] =
    "墨と淡彩による中国の絵巻で, 衰えゆく蓮の池を間近にとらえた自然の写生である. 赤, 緑, 青の蜻蛉が枯れゆく葦やぼろぼろになった蓮の葉の上を舞い, その下ではバッタ, 蜂, 小さな蛙たちがめいめいに過ごしている. 趣はおだやかな衰退であり, 枯れ始めたばかりの草の間で夏の生命が続いており, 両端には赤い収蔵印が並んでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_APPRECIATING_LOTUSES"] =
    "狩野派の祖による墨と淡彩の掛軸で, 中国の文人山水の様式で描かれている. ローブを纏った中国の文人が蓮の池の縁で小舟に揺られ, 岩の多い岸から張り出すごつごつとした柳の下で, 浮かぶ葉に見入っている. 縦長の軸のほとんどは霧と開けた水面で, わずかな松の梢が霞の中へと消えていく."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EQUESTRIAN_PORTRAIT"] =
    "ヴェネツィア・ルネサンスの油彩画で, 馬上の君主を描く以後数世紀の手本となった一枚である. 神聖ローマ皇帝が, 赤い羽根飾りのついた兜をかぶり, 槍を手にして, 輝く全身甲冑で暗い森から馬を進めており, ミュールベルクでの勝利を記念している. 黒い馬には深紅の馬掛けが掛けられ, 低い夕日が重い嵐雲の下に金とピンクの光を射し込ませている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ARMADA"] =
    "スペイン無敵艦隊の敗北を祝うために描かれた, チューダー朝の宣伝的な油彩肖像画. 女王エリザベス1世は真珠とリボンで覆われた壮大なガウンを着て座り, その顔は広大な白いレースのひだ襟に縁取られ, 片手は地球儀の上に所有を誇るように置かれ, 指はアメリカ大陸に触れている. 背後の窓を通して物語が二度語られる. 片側では穏やかな海に浮かぶイングランド艦隊, もう片側では嵐の中で難破するスペインの船. 宝石をちりばめた王冠が彼女の傍らに置かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRANCIS_I"] =
    "フランス・ルネサンスの王の油彩肖像画. フランス国王フランソワ1世は腰から上を見る者に向け, 華麗な宮廷衣装を纏う. 白と金のサテンに黒い縞を入れた切れ込みのある袖, 胸を横切る金の鎖, 頭には白い羽根飾りの付いた黒い帽子. 抜け目のない, 鼻の長い髭面が, 王冠の文様を散らした深紅のダマスク織りの背景の中で際立っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SELF_PORTRAIT"] =
    "皇帝ルドルフ2世のフランドル宮廷画家による, 北方マニエリスムの油彩の自画像. 画家は肩越しに見る者を振り返る. 柔らかな黒い帽子の下に巻き毛をたくわえた頑丈な髭面の男で, 灰青色のダブレットの上に白いひだ襟を着けている. 筆致は無地の茶色の背景を背に温かく直接的で, その品定めするような横目の視線が見る者の目を捉えて離さない."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VERTUMNUS"] =
    "マニエリスムの油彩画で, アルチンボルドの幻想的な寄せ絵の頭部の中で最も有名な作品. 皇帝ルドルフ2世をローマの季節の神ウェルトゥムヌスとして描いた肖像で, その顔と胸の全体が果物, 野菜, 花で組み立てられている. 豆のさやのまぶた, 洋梨の鼻, さくらんぼの唇, 麦の穂のもみあげ, 葡萄の髪. 遠目には威厳ある統治者だが, 近くで見ると市場の露店へと崩れていく. すべてが黒い背景の中に置かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_SUPPER"] =
    "見慣れた場面を作り変えた, ヴェネツィア後期ルネサンスの油彩画. 最後の晩餐の食卓は見る者に正面から向き合うのではなく, 急な斜めの角度で暗い酒場の広間の奥へと突き進んでいき, キリストはその長さの半ばで光を放ちながら使徒たちにパンを差し出す. 召使いたちが食事を運び, 前景では猫が籠に鼻を突っ込んでいる. その頭上では燃え盛る油灯が煙る空気を満たし, 半透明の渦巻く天使たちが浮かんでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_A_MAN"] =
    "初期ネーデルラントの油彩画で, おそらく画家自身の顔を描いた, 最初期の真の自画像の一つ. 皺の刻まれた鋭い目をした中年の男が, 深い影の中から見る者をまっすぐ見つめ, 巻いて結び彫刻のようなひだを成した派手な赤い被り物を着けている. 描写は針のように緻密で, あらゆる皺と無精髭の一本まで捉えられており, 黒い背景を背に, この人物は暗い毛皮の縁取りのコートを着ている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRONT_OF_THE_MIRROR"] =
    "ヴェネツィア・ルネサンスの油彩画で, 老いたベリーニの穏やかな晩年の傑作. 赤い布の上に座る赤褐色の髪の裸の若い女が, 小さな手鏡を持ちながら静かに髪を整え, 背後の壁に掛かったもう一つの丸い鏡が, 文様のある被り物の後ろ姿を映している. 彼女の傍らの窓は, 雲の浮かぶ空の下, 遠くの青い山々を望む緑の田園へと開いている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ADORATION"] =
    "スクロヴェーニ礼拝堂の初期イタリアのフレスコ画で, 自然な人間の感情を西洋美術に呼び戻したとされる画家による東方三博士の礼拝. 木の天蓋の下, マリアが幼子キリストを抱き, 三人の王の最年長者が冠を脇に置いて跪き, 幼子の足に口づけする. 左手には駱駝が控えている. 厩の上方では, いつもの星に代わって彗星が深い青の空を横切って尾を引く. すべてがジョットの堅固で簡潔な人物と明快な色彩で描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUBENS_AND_ISABELLA"] =
    "フランドル・バロックの油彩画で, 画家が自身と花嫁を描いた結婚の肖像. 若い夫婦はすいかずらの茂みの下に寄り添って座り, 彼女の右手が彼の手の上に優しく重ねられ, それがこの絵の静かな中心となっている. 彼は黒いダブレットを着て片脚を組み, 彼女より高い位置に座り, 彼女は紫のスカート, 金の刺繍を施したボディス, 幅広のひだ襟, 高い麦わら帽子をまとって跪き, 二人とも穏やかな満足の表情で外を見やっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CHILDS_BATH"] =
    "日々の慈愛を描いたアメリカ印象派の油彩画で, 高い視点と平らな文様に日本の版画の影響が見られる. 大胆な縞模様のドレスを着た母が, タオルにくるんだ子供を膝に抱き, 洗面器の水でその小さな子の足を洗う. 二つの頭はこの仕事の上で寄り添って傾き, 二人を取り巻く部屋は文様のつぎはぎだ. 花柄の壁紙, 彩色された箪笥, 装飾的な絨毯, そして白い水差し."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_CARD_PLAYERS"] =
    "この主題を扱った有名な連作の一つである, ポスト印象派の油彩画. 帽子をかぶった二人の農夫の男が小さな木の卓を挟んで向かい合って座り, カードに没頭し, 一本のワイン瓶が二人の間に立って構図の静かな中心を成している. 一人はパイプをくゆらせる. 絵具は土色の茶, 黄土色, くすんだ紫の根気強い角張った筆致で積み重ねられ, 人物たちは彫り出されたように永続的に感じられる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_SWING"] =
    "フランス・ロココの油彩画で, 軽薄で秘めやかな, この時代の最も有名な絵. 鬱蒼と生い茂る豊かな庭で, 泡立つようなピンクのドレスを着た若い女がぶらんこのロープに乗って高く揺れ, 片方の上靴を空中に蹴り上げる一方, 隠れた年配の男が彼女の背後の影からロープを引いている. 彼女の若い恋人は下のばらの茂みに身を投げ出し, 彼女のスカートの中を見上げるのにうってつけの位置にいて, 石のキューピッド像が指を唇に当てている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIANT_MAGNOLIAS"] =
    "アメリカの静物油彩画で, 豊かでほとんど熱帯的な趣がある. 二輪の巨大なクリーム色の白いマグノリアの花が, 深い青のビロードの掛け布の上に切り取られて横たわり, 艶やかな濃い葉に囲まれ, 三つ目のつぼみはまだ閉じている. 花弁は黒に近い背景を背に輝き, 蝋のような官能的な精緻さで描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_KILLING"] =
    "テンペラと金によるカタルーニャ・ゴシックの板絵による聖ゲオルギウスの竜退治. 黒い甲冑に金の光輪をいただく聖ゲオルギウスが, 棒立ちになった白馬から身を乗り出し, 蝙蝠の翼を持つ竜の開いた口へと長い槍を突き下ろし, 周囲の地面は骨と頭蓋骨で散らかっている. ピンクのガウンを着た王女が背後の岩の露頭で祈り, 上方の白い城壁には見物人が群がっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JACQUES_AND_BERTHE"] =
    "彫刻家リプシッツとその妻を描いたモダニズムの油彩二人肖像で, モディリアーニのまぎれもない様式で描かれている. 夫は暗い背広姿で立ち, 片手を座る妻の肩に置いている. 妻の頬はバラ色で, 顔は白いレースの衿から立ち上がっている. 二人ともこの画家特有の引き伸ばされた顔, 長い鼻, うつろなアーモンド形の目をしており, 二人の名がカンバスの上端に走り書きされている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DASH_FOR_TIMBER"] =
    "アメリカ西部を題材にした油彩画で, 大衆の想像の中で古き西部を形づくった, あの突進する動きの場面の類いだ. 8人のカウボーイが全力で見る者へまっすぐ駆け寄り, 馬の蹄は地を離れ, うち二人は鞍の上で身をひねり, 砂塵を上げて追ってくる騎乗のアパッチの一団へ撃ち返している. 一人は傷を負って仲間にもたれかかり, 乾いた平原の左端の木立を目指して疾走している."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GEORGE_WASHINGTON_PORTRAIT"] =
    "アメリカの国家肖像の油彩で, 初代大統領職の公式の姿だ. ワシントンは飾りのない黒いビロードの衣装をまとって全身像で立ち, 片腕を演説の身振りで差し伸べ, もう一方の手には儀礼用の剣を持ち, 羽ペンとインク台を載せた机の脇にいる. 彼を取り巻く調度は共和制の壮麗さで, 星条旗の盾を付けた金箔張りの椅子, 大理石の柱, 深紅の垂れ幕の襞飾りがあり, その奥では嵐雲を破って虹が差している."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ATTACK_ON_BEIJING"] =
    "戦時の報道挿絵の様式による日本の多色刷り版画で, 日本語と英語の両方で説明が添えられている. 連合軍の兵が北京の皇城の城壁に突入する. 前面ではユニオンジャックを掲げた赤い上着のイギリス兵が突撃し, 右では白い軍服の日本軍の歩兵が前進している. 砲弾の炸裂が緑の練兵場の上に白い煙の塊となって漂い, その奥には皇城の青い屋根の門と煙を上げる城壁がある."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUMO_WRESTLER"] =
    "日本の浮世絵木版画で, 非番の人気力士を描いた著名人の肖像だ. この大男が文様のあるローブの上に黒い着物を羽織って全身を伸ばして立ち, 腰には刀を差し, 格子柄の布で額を拭いながら, 包んだ羽織を片方の肩に担いでいる. その名は右側に大胆な朱の書文字の枠で縦に走り, 平面的で記念碑的な姿が無地の紙の上に描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_TIGER_IN_TROPICAL_STORM"] =
    "ジャングルを一度も見たことのない独学のフランス人税関吏による素朴派様式の油彩画だ. 目を見開いたトラが風になびく丈高い草の中に低く身を伏せ, 牙をむき出し, あらゆる植物を横倒しにする嵐の中に捉えられている. ジャングルは緑と赤で様式化された葉の密な文様で, 斜めに走る銀色の雨の筋が薄絹のようにカンバス全体に引かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_HOME_GUARD"] =
    "1848年の革命を題材にしたハンガリーのビーダーマイヤー様式の油彩肖像だ. 顎鬚を蓄えた市民兵が飾りのない無染色の亜麻の上着を着て座り, 手袋をはめた両手を立てたサーベルの柄に置き, 袖には赤, 白, 緑の国の腕章を付けてその大義を表している. 彼は穏やかな決意をたたえて横へ視線を向け, 暗い赤のカーテンを背に温かく照らされ, 赤い裏地のコートが椅子に掛けられている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CEREMONIAL_SITTING"] =
    "巨大な規模のロシア写実主義の油彩画で, 帝国の統治評議会全体を描いた集団肖像だ. 金モールと赤い飾り帯で重厚に飾られた暗い制服をまとう数十人の年配の政治家たちが, シャンデリアと王族の肖像が掛かる白い柱の広間で, 赤い椅子の大きな馬蹄形を囲んで座っている. 60を超える顔の一つ一つが個別の肖像であり, レーピンの素早く自信に満ちた写実で描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUSSIAN_TSAR"] =
    "16世紀の王室行列を再現したロシアの歴史油彩画だ. 毛皮の帽子をかぶり金襴のローブをまとった皇帝が雪の中を白馬に乗って進み, その前を鮮やかな赤い上着の衛兵たちが長い湾曲したポールアックスを担いで歩く. 踏み荒らされた雪の道の両側では群衆がひざまずいて地に伏し, 淡い冬空の下に古いロシアの町の丸太造りの建物が並んでいる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CRUCIFIXION_OF_SAINT_PETER"] =
    "イタリア・バロックの油彩画で, カラヴァッジョの特徴的な様式による残酷で肉体的な作品だ. 3人の労働者が, 年老いた聖ペテロが逆さに釘付けにされた木の十字架を懸命に引き起こそうとしており, 一人は綱を引き, もう一人は梁の下にうずくまり, その顔は隠れている. 白い顎鬚の聖人は頭を持ち上げて自らの釘付けにされた手を見つめ, 筋肉質の老いた体が一筋の硬い光の中で漆黒の闇から輝き出している."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LANDSCAPE_WITH_ANT_BEAR"] =
    "ブラジルで活動した最初のヨーロッパで訓練を受けた画家による, オランダ植民地時代の油彩風景画だ. 川の流れる広い陽光の谷が, 2本の高いヤシの間で大きな空の下に開け, 遠い丘には白い家々の植民地の集落がある. 前面ではアフリカ系ブラジル人の一団が荷を担いで小道を歩き, 題名のオオアリクイ, あの長い鼻の動物が右下の低木の茂みを鼻でかき分けている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DUTCH_MEN_O_WAR"] =
    "船を描かせては当代随一の画家による, オランダ黄金時代の海洋油彩画だ. 背の高い木造の軍艦がガラスのように滑らかな水面に錨を下ろし, 帆はだらりと垂れ, 船体は海に映り, 索具の一本一本まで正確に描かれている. 手漕ぎの小舟が, 陽光に照らされた積雲の広大な空の下で船から船へと乗客を運び, 場面全体が金色の静けさに浸されている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HARBOR_IN_BALAKLAVA"] =
    "クリミア戦争を描いた淡彩のリトグラフで, 戦役を現地で記録した最初の従軍画家の一人によって描かれた. 荒涼とした港の岸辺で, 白い毛布にくるまれた病人や負傷兵が, ラバに担がれた担架から待ち受ける手漕ぎ舟へと助け降ろされている. ひしめく人々の背後には木のない茶色の丘がそびえ, 斜面には軍の小屋やテントが点在し, 色彩は抑えられて記録的だ."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PEACEMAKERS"] =
    "南北戦争末期の実際の作戦会議を描いたアメリカの歴史油彩画だ. リンカーン大統領が蒸気船の船室で頬杖をついて熱心に耳を傾け, シャーマン将軍が議論の途中で身振りをまじえている. グラント将軍とポーター提督が, 暗い背広姿の4人の輪を完成させている. 彼らの背後の船室の窓越しには, 晴れていく空を破って虹が差しており, この絵が描く来るべき平和の静かな兆しだ."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_CHITASEI"] =
    "中国の小説水滸伝の108人の英雄を描いた国芳の名高い連作からの, 日本の浮世絵木版画だ. 学者にして軍師の呉用が竜の文様の入った流れるような暗いローブをまとって立ち, 星をちりばめた夜空の下で物思いにふけりながら顎鬚をなでている. その傍らには精巧な台に載った大きな天球儀が置かれ, 日本語の文字の枠がこの人物を縁取っている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_LOUIS"] =
    "制作中の彫刻家を捉えた, 18世紀イギリスの油彩肖像画. ルビヤックは柔らかな帽子をかぶり, 袖をまくった前開きのシャツ姿で, 造形用の工具を持つ手を上げたまま手を止め, 台の上で制作中のシェイクスピアの粘土像へ視線を横に向けている. 彫刻家はもう一方の手で自らの作品を指し, 暗いアトリエの背景の中に温かな光を浴びている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_NASSER"] =
    "王の威光を厚く塗り重ねた, ペルシアのガージャール朝の宮廷油彩肖像画. 口髭を蓄えた若きシャーは, 金の刺繍をびっしりとあしらった緋色の軍服を身につけ, 真珠の数連の飾り, 宝石をちりばめた肩章, 青のたすきを帯び, 片手を宝石付きの剣に置いて, こわばった姿勢で背筋を伸ばして座る. ダイヤモンドの飾りを差した背の高い黒い帽子をかぶり, 黒く縁取られた両目で, 王の銘文が刻まれた深いオリーブ色の背景を背に外を見つめている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FIELD_WITH_SHEAFS"] =
    "ドイツ表現主義に傾いた油彩の風景画で, 広く力強い筆致で描かれている. 刈り入れの済んだ麦畑が前面を埋め, 黄金色の麦束が傾いて積まれた列を成し, 黄は厚く明るく塗られている. 濃い緑の木々の列が畑を奥で閉じ, その上には風に流れる雲の浮かぶ淡い菫青色の空が広がっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AT_THE_EDGE_OF_THE_BROOK"] =
    "ブグローが名声を得たガラスのような完璧さに磨き上げられた, フランス・アカデミーの油彩画. 裸足の農村の子供2人が小川の畔の石の上に座り, 年下の少女が靴下を脱ぎ, 黒髪の連れは水に入ろうとスカートをたくし上げている. 2人は会話の途中で視線を交わし, その肌と乱れた髪は柔らかな田園風景を背に写真のような滑らかさで描かれている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS_ALT"] =
    "イタリア美術で最も名高い接吻にして, 統一運動の隠された愛国の象徴となった, イタリア・ロマン主義の油彩画. 中世の石造りの廊下で, 羽根飾りのついた帽子をかぶり茶色のマントを羽織った若い男が, 女性を後ろへ反らせて情熱的に口づけし, 逃避の途中で足を止めたかのように片足をすでに階段に掛けている. 彼女の淡い青のサテンのドレスがこの場に光を注ぎ込み, その奥のアーチの向こうからは影のような人影が近づいてくる."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MOVING_HOUSE"] =
    "都市の静かな貧しさを描いた, ロシア・リアリズムの油彩画. 年老いた夫婦が, 持てる物すべてを布の包みにまとめて運びながら, サンクトペテルブルクの凍った川の氷の上をとぼとぼと歩いて渡る. 男は杖にすがり, 2人とも擦り切れた外套と頭巾で寒さに身を包んでいる. 小さな犬が2人の先を駆け, 背後にはペトロパヴロフスク要塞の金色の尖塔が冬の靄を貫いて立ち上がっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MEXICAN_EXPEDITION"] =
    "ルポルタージュ風で動きに満ちた, フランス海軍の歴史を描いた油彩画. 三色旗を掲げたフランスの軍艦が左の前面を占め, その甲板上の士官たちがメキシコのサン・フアン・デ・ウルア要塞への砲撃を指揮し, 水面に煙が立ち上る. 砲弾は船から船へ兵を運ぶ手漕ぎ舟の近くに水しぶきを上げ, 霞んだ水平線には雪をいただいた火山が見える."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_DAY_OF_POMPEII"] =
    "巨大な画布に描かれた, その世紀の災厄叙事詩というべきロシア・ロマン主義の油彩画. ヴェスヴィオ火山が噴火し, ポンペイの空は赤と黒に燃え, 屋根からは像が倒れ落ち, 稲妻が灰の雲を切り裂く. ローマ風の衣装を着た町の人々の群れが降りそそぐ瓦礫の中を逃げ, マントで子供や老人をかばい, 中央では転倒した戦車の脇にひとりの女が倒れ伏している."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ACCOLADE"] =
    "騎士道を物語絵のように描いた, イギリスのラファエル前派風の油彩画. 流れるような白いガウンを纏った金髪の女王が, ひざまずく騎士の肩に剣を当て, 小さな宮廷の人々の前で彼に騎士号を授けている. 騎士は鎖帷子と赤いサーコートを身につけて頭を垂れ, その脇の床には兜が置かれている. 石造りの広間と赤い壇は, きらめくロマンティックな細部で描かれている."
